import {createStudy,canvasSurface,clamp,downloadCanvas} from './core.js';
const study=createStudy({id:13,title:'Soft Machinery',category:'Physics / Fabric',accent:'#efc866',background:'#491329',foreground:'#f4d68f'});
const canvas=document.querySelector('#fabric-canvas'),surface=canvasSurface(canvas,{maxDpr:1.5});
const cols=24,rows=16;let points=[],constraints=[],wind=70,drag=null,released=false;
function idx(x,y){return y*(cols+1)+x}
function reset(restoreControls=false){if(restoreControls){wind=70;document.querySelector('#fabric-wind').value=70;document.querySelector('#fabric-wind-value').textContent=70}canvas.style.cursor='default';document.querySelector('#fabric-status').textContent='A woven study. Drag the cloth to feel its constraints.';const{width:w,height:h}=surface;const clothWidth=Math.min(w*.58,650),clothHeight=Math.min(h*.56,420),startX=w<600?w*.19:w*.35,startY=h*.16;points=[];constraints=[];for(let y=0;y<=rows;y++)for(let x=0;x<=cols;x++){const xx=startX+x/cols*clothWidth,yy=startY+y/rows*clothHeight+Math.sin(x/cols*Math.PI)*y/rows*14;points.push({x:xx,y:yy,px:xx-1.3*Math.sin(y*.3),py:yy,pin:y===0&&(x===0||x===cols),ax:xx,ay:yy})}for(let y=0;y<=rows;y++)for(let x=0;x<=cols;x++){if(x<cols)add(idx(x,y),idx(x+1,y));if(y<rows)add(idx(x,y),idx(x,y+1));if(x<cols&&y<rows)add(idx(x,y),idx(x+1,y+1))}drag=null;released=false;document.querySelector('#fabric-tether').setAttribute('aria-pressed','false');document.querySelector('#fabric-tether').innerHTML='RELEASE THE RIGHT TETHER <span aria-hidden="true">↘</span>';draw();}
function add(a,b){constraints.push({a,b,length:Math.hypot(points[a].x-points[b].x,points[a].y-points[b].y)})}
function simulate(dt,time){if(dt<=0)return;const h=surface.height,w=surface.width;const step=Math.min(dt,.028);for(const p of points){if(p.pin||p===drag)continue;const vx=(p.x-p.px)*.984,vy=(p.y-p.py)*.984;p.px=p.x;p.py=p.y;p.x+=vx+Math.sin(time*1.2+p.y*.011)*wind*step*step*3.8;p.y+=vy+330*step*step}for(let iteration=0;iteration<6;iteration++){for(const link of constraints){const a=points[link.a],b=points[link.b],dx=b.x-a.x,dy=b.y-a.y,length=Math.hypot(dx,dy)||.001,delta=(length-link.length)/length*.5;if(!a.pin&&a!==drag){a.x+=dx*delta;a.y+=dy*delta}if(!b.pin&&b!==drag){b.x-=dx*delta;b.y-=dy*delta}}for(const p of points){if(p.pin){p.x=p.ax;p.y=p.ay;p.px=p.x;p.py=p.y}p.x=clamp(p.x,12,w-12);p.y=clamp(p.y,10,h-39)}}}
function draw(){const{ctx,width:w,height:h}=surface;if(!ctx)return;ctx.clearRect(0,0,w,h);ctx.fillStyle='#491329';ctx.fillRect(0,0,w,h);const gl=ctx.createRadialGradient(w*.73,h*.4,0,w*.73,h*.4,w*.55);gl.addColorStop(0,'#6e253e');gl.addColorStop(1,'#491329');ctx.fillStyle=gl;ctx.fillRect(0,0,w,h);ctx.save();ctx.shadowColor='#19041477';ctx.shadowBlur=35;ctx.shadowOffsetY=18;ctx.beginPath();for(let y=0;y<=rows;y++){const p=points[idx(cols,y)];y?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)}for(let y=rows;y>=0;y--){const p=points[idx(0,y)];ctx.lineTo(p.x,p.y)}ctx.closePath();ctx.fillStyle='#a56c2b';ctx.fill();ctx.restore();for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const a=points[idx(x,y)],b=points[idx(x+1,y)],c=points[idx(x+1,y+1)],d=points[idx(x,y+1)];const slope=Math.atan2(b.y-a.y,b.x-a.x);const shade=clamp(58+Math.sin(slope*3+x*.38)*17-y/rows*6,35,82);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.lineTo(c.x,c.y);ctx.lineTo(d.x,d.y);ctx.closePath();ctx.fillStyle=`hsl(42 72% ${shade}%)`;ctx.fill();ctx.strokeStyle='#6e481f25';ctx.lineWidth=.5;ctx.stroke()}for(let x=0;x<=cols;x+=3){ctx.beginPath();for(let y=0;y<=rows;y++){const p=points[idx(x,y)];y?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)}ctx.strokeStyle='#fff0bd33';ctx.lineWidth=.55;ctx.stroke()}for(const p of points.filter(p=>p.pin)){ctx.beginPath();ctx.arc(p.x,p.y,8,0,Math.PI*2);ctx.fillStyle='#491329';ctx.fill();ctx.strokeStyle='#f4d68f';ctx.lineWidth=1.5;ctx.stroke();ctx.beginPath();ctx.arc(p.x,p.y,2,0,Math.PI*2);ctx.fillStyle='#f4d68f';ctx.fill()}if(drag){ctx.beginPath();ctx.arc(drag.x,drag.y,11,0,Math.PI*2);ctx.strokeStyle='#fff1c8';ctx.lineWidth=1;ctx.stroke()}}
function pointer(event){const r=canvas.getBoundingClientRect();return{x:event.clientX-r.left,y:event.clientY-r.top}}
canvas.addEventListener('pointerdown',event=>{const p=pointer(event);let closest=null,distance=70;for(const point of points){const d=Math.hypot(point.x-p.x,point.y-p.y);if(d<distance){distance=d;closest=point}}drag=closest;if(drag){canvas.setPointerCapture(event.pointerId);canvas.style.cursor='grabbing'}});
canvas.addEventListener('pointermove',event=>{const p=pointer(event);if(drag){drag.x=drag.px=clamp(p.x,12,surface.width-12);drag.y=drag.py=clamp(p.y,10,surface.height-39);if(drag.pin){drag.ax=drag.x;drag.ay=drag.y}study.invalidate()}else canvas.style.cursor=points.some(point=>Math.hypot(point.x-p.x,point.y-p.y)<50)?'grab':'default'});
for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,()=>{drag=null;canvas.style.cursor='default'});
document.querySelector('#fabric-wind').addEventListener('input',event=>{wind=+event.target.value;document.querySelector('#fabric-wind-value').textContent=wind;study.invalidate()});
document.querySelector('#fabric-tether').addEventListener('click',()=>{const p=points[idx(cols,0)];released=!released;p.pin=!released;if(!released){p.ax=p.x;p.ay=p.y}document.querySelector('#fabric-tether').setAttribute('aria-pressed',String(released));document.querySelector('#fabric-tether').innerHTML=released?'PIN IT WHERE IT IS <span aria-hidden="true">↗</span>':'RELEASE THE RIGHT TETHER <span aria-hidden="true">↘</span>';document.querySelector('#fabric-status').textContent=released?'One tether released. The whole cloth finds another balance.':'The right tether is pinned again.';study.invalidate()});
study.setReset(()=>reset(true));study.setExport(()=>downloadCanvas(canvas,'13-soft-machinery.png'));study.onResize(reset);study.onFrame(({dt,time})=>{simulate(dt,time);draw()});study.cleanup(()=>surface.dispose());reset();
